import{_ as i,a0 as d,w as r,s,ao as p,I as e,x as t,a1 as n,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const G=JSON.parse('{"title":"安卓編年史（23）：Android 4.3，果凍豆——早早支持可穿戴設備 | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史（23）：Android 4.3，果凍豆——早早支持可穿戴設備 | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史（23）：Android 4.3，果凍豆——早早支持可穿戴設備 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史（23）：Android 4.3，果凍豆——早早支持可穿戴設備 | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/24 - The history of Android","title":"安卓編年史（23）：Android 4.3，果凍豆——早早支持可穿戴設備","tag":"The history of Android","desc":""},"relativePath":"The history of Android/24 - The history of Android.md","filePath":"[post].md"}'),m={name:"The history of Android/24 - The history of Android.md"};function g(u,o,A,f,y,T){const a=d("Link");return r(),s("div",null,[o[20]||(o[20]=p('<h1 id="安卓編年史-23-android-4-3-果凍豆——早早支持可穿戴設備" tabindex="-1">安卓編年史（23）：Android 4.3，果凍豆——早早支持可穿戴設備 <a class="header-anchor" href="#安卓編年史-23-android-4-3-果凍豆——早早支持可穿戴設備" aria-label="Permalink to “安卓編年史（23）：Android 4.3，果凍豆——早早支持可穿戴設備”">​</a></h1><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/Goooogleplaymusic.jpg" alt="漂亮的新 Google Play Music 應用，從電子風格轉向完美契合 Play 商店的風格。"></p><p><em>漂亮的新 Google Play Music 應用，從電子風格轉向完美契合 Play 商店的風格。 [Ron Amadeo 供圖]</em></p><p>在 I/O 大會推出的另一個應用更新是 Google Music 應用。音樂應用經過了完全的重新設計，最終擺脱了蜂巢中引入的藍底藍色調的設計。Play Music 的設計和幾個月前發佈的 Play 商店一致，有着響應式的白色卡片佈局。Music 同時還是最早採用新抽屜導航樣式的主要應用之一。谷歌還隨新應用發佈了 Google Play Music All Access，每月 10 美元的包月音樂訂閲服務。Google Music 現在擁有訂閲計劃，音樂購買，以及雲端音樂存儲空間。這個版本還引入了“Instant Mix”，谷歌會在雲端給相似的歌曲計算出一份歌單。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/gooooogleplaygames.jpg" alt="一個展示對 Google Play Games 支持的遊戲。上面是 Play 商店遊戲特性描述，登陸游戲觸發的權限對話框，Play Games 通知，以及成就界面。"></p><p><em>一個展示對 Google Play Games 支持的遊戲。上面是 Play 商店遊戲特性描述，登陸游戲觸發的權限對話框，Play Games 通知，以及成就界面。 [Ron Amadeo 供圖]</em></p><p>谷歌還引入了 “Google Play Games”，一個後端服務，開發者可以將其附加到遊戲中。這項服務簡單説就是安卓版的 Xbox Live 或蘋果的 Game Center。開發者可以給遊戲添加 Play Games 支持，這樣就能通過使用谷歌的後端服務，更簡單地將成就、多人遊戲、遊戲配對、用户賬户以及雲端存檔集成到遊戲中。</p><p>Play Games 是谷歌在遊戲方面推進的開始。就像單獨的 GPS 設備，翻蓋手機，以及 MP3 播放器，智能手機的生產者希望遊戲設備能夠變成智能手機的一個功能點。當你有部智能手機的時候你為什麼還有買個任天堂 DS 或 PS Vita 呢？一個易於使用的多人遊戲服務是這項計劃的重要部分，我們仍能看到這個決定最後的成果。在今天，坊間都在傳言谷歌和蘋果有關於客廳遊戲設備的計劃。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/goooglekeep.jpg" alt="Google Keep，谷歌自 Google Notebook 以來第一個筆記服務。"></p><p><em>Google Keep，谷歌自 Google Notebook 以來第一個筆記服務。 [Ron Amadeo 供圖]</em></p>',10)),e("p",null,[o[1]||(o[1]=t("毫無疑問一些產品為了趕上 Google I/O 大會的發佈準時開發完成了，",-1)),n(a,{href:"http://live.arstechnica.com/liveblog-google-io-2013-keynote/"},{default:l(()=>[...o[0]||(o[0]=[t("但是三個半小時內的主題",-1)])]),_:1}),o[2]||(o[2]=t("已經夠多了，一些產品在大會的發佈上忽略了。Google I/O 大會的三天後一切都清楚了，谷歌帶來了 Google Keep，一個用於安卓和在線的筆記應用。Keep 看起來很簡單，就是一個用上了響應式 Google-Now 風格設計的筆記應用。用户可以改變卡片的尺寸，從多欄佈局改為單列視圖。筆記可以由文本，清單，自動轉文本的語音或者圖片組成。筆記卡片可以拖動並在主界面重新組織，你甚至可以給筆記換個顏色。",-1))]),o[21]||(o[21]=p(`<p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/05/gmail.png" alt="Gmail 4.5，換上了新的導航抽屜設計，去掉了幾個按鈕並將操作欄合併到了抽屜裏。"></p><p><em>Gmail 4.5，換上了新的導航抽屜設計，去掉了幾個按鈕並將操作欄合併到了抽屜裏。 [Ron Amadeo 供圖]</em></p><p>在 I/O 大會之後，沒有哪些應用沒出現在谷歌的週期外更新裏。2013 年 6 月，谷歌發佈了新版設計的 Gmail。最顯眼的變化就是一個月前 Google I/O 大會引入的新導航抽屜界面。最吸引眼球的變化是用上了 Google+ 資料圖片來取代複選框。雖然複選框看起來被去掉了，它們其實還在那，點擊郵件左邊的圖片就是了。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/newmaps11.png" alt="新谷歌地圖，換上了全白的 Google-Now 風格主題。"></p><p><em>新谷歌地圖，換上了全白的 Google-Now 風格主題。 [Ron Amadeo 供圖]</em></p><p>一個月後，谷歌在 Play 商店發佈了全新的谷歌地圖。這是谷歌地圖自冰淇淋三明治以來第一個經過細緻地重新設計的版本。新版本完全適配了 Google Now 白色卡片審美，還大大減少了屏幕上顯示的元素。新版谷歌地圖似乎設計時有意使地圖總是顯示在屏幕上，你很難找到除了設置頁面之外還能完全覆蓋地圖顯示的選項。</p><p>這個版本的谷歌地圖看起來活在它自己的小小設計世界中。白色的搜索欄“浮動”在地圖之上，地圖顯示部分在它旁邊和上面都有。這和傳統的操作欄設計有所不同。一般在應用左上角的導航抽屜，在這裏是在左下角。這裏的主界面沒有向上按鈕、應用圖標，也沒有浮動按鈕。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/newmaps21.png" alt="新谷歌地圖輕量化了許多，在一屏內能夠顯示更多的信息。"></p><p><em>新谷歌地圖輕量化了許多，在一屏內能夠顯示更多的信息。 [Ron Amadeo 供圖]</em></p><p>左邊的圖片顯示的是點擊了搜索欄後的效果（帶鍵盤，這裏關閉了）。過去谷歌在空搜索欄下面顯示一個空頁面，但在地圖中，谷歌利用這些空間鏈接到新的“本地”頁面。搜索結果頁顯示一般信息的結果，比如餐館、加油站，以及景點。在結果頁的底部是個列表，顯示你的搜索歷史和手動緩存部分地圖的選項。</p><p>右側圖片顯示的是地點頁面。上面地圖 7.0 的截圖裏顯示的地圖不是略縮圖，它是完整的地圖視圖。在新版的谷歌地圖中，地點作為卡片浮動顯示在主地圖之上，地圖重新居中顯示該地點。向上滑動可以讓卡片覆蓋地圖，向下滑動可以顯示帶有底部一小條結果的完整地圖。如果該地點是搜索結果列表中的一個，左右滑動可以在結果之間切換。</p><p>地點頁面重新設計以顯示更有用的信息概覽。在第一頁，新版添加了重要信息，比如地圖上的位置，點評得分，以及點評數目。因為這是個手機，所以軟件內可以直接撥打電話，電話號碼的顯示被認為是毫無意義的，被去掉了。舊版地點顯示到那裏的距離，新版谷歌地圖顯示到那裏的時間，基於交通狀況和偏好的交通方式——一個更加實用的衡量方式。新版還在中間放了個分享按鈕，這使得通過即時通訊或短信協調的時候更加方便。</p><h3 id="android-4-3-果凍豆——早早支持可穿戴設備" tabindex="-1">Android 4.3，果凍豆——早早支持可穿戴設備 <a class="header-anchor" href="#android-4-3-果凍豆——早早支持可穿戴設備" aria-label="Permalink to “Android 4.3，果凍豆——早早支持可穿戴設備”">​</a></h3><p>如果谷歌沒有在安卓 4.3 和安卓 4.2 之間通過 Play 商店發佈更新的話，安卓 4.3 會是個不可思議的更新。如果新版 Play 商店、Gmail、地圖、書籍、音樂、Hangouts 環聊，以及 Play Games 打包作為新版安卓的一部分，它將會作為有史以來最大的發佈受到歡呼。雖然谷歌沒必要延後新功能的發佈。有了 Play 服務框架，只剩很少的部分需要系統更新，2013 年 7 月底谷歌發佈了看似無關緊要的“安卓 4.3”。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/2014-03-28-12.231.jpg" alt="安卓 4.3 通知訪問權限界面的可穿戴設備選項。
"></p><p><em>安卓 4.3 通知訪問權限界面的可穿戴設備選項。 [Ron Amadeo 供圖]</em></p><p>谷歌也毫無疑問地認為 4.3 的重要性不高，將新版也叫做“果凍豆”（第三個叫果凍豆的版本了）。安卓 4.3 的新功能列表像是谷歌無法通過 Play 商店或谷歌 Play 服務更新的部分的細目清單，大部分包含了為開發者作出的底層架構改動。</p><p>但許多新增功能似乎只為了一個目的——安卓 4.3 是谷歌對可穿戴計算支持的特洛伊木馬。4.3 加入了低功耗藍牙支持，使用很少的能耗將安卓和其它設備連接到一起並傳輸數據——可穿戴設備的必要特性。安卓 4.3 還添加了“通知訪問權限”API，允許應用完全複製和控制通知面板。應用可以顯示通知文本以及和用户操作一樣地和通知交互——也就是點擊操作按鈕和消除通知。當你有個通知面板時從本機應用做這個操作沒什麼意義，但是在一個獨立於你手機的設備上，複製通知面板的消息就顯得很有用了。為數不多的接入的應用是 “Android Wear Preview（安卓可穿戴預覽）”，使用了通知 API 驅動大部分的 Android Wear 界面。</p>`,18)),e("p",null,[o[4]||(o[4]=t("“4.3 是給可穿戴設備準備的”這個理論解釋了 4.3 相對較少的新特性：它的推出是為了給 OEM 廠商時間去升級設備，為 ",-1)),n(a,{href:"http://arstechnica.com/gadgets/2014/03/in-depth-with-android-wear-googles-quantum-leap-of-a-smartwatch-os/"},{default:l(()=>[...o[3]||(o[3]=[t("Android Wear",-1)])]),_:1}),o[5]||(o[5]=t(" 的發佈做準備。這個計劃看起來起作用了。Android Wear 要求 安卓 4.3 及以上版本，安卓 4.3 已經發布很長時間了，大部分主要的旗艦設備都已經升級了。",-1))]),o[22]||(o[22]=e("p",null,"安卓並沒有那麼激動人心，但安卓從現在起的新版也不需要那麼激動人心了。一切都變得那麼模組化了，谷歌可以通過 Google Play 在它們完成時隨時推送更新，不用再作為一個大系統更新來更新這麼多組件。",-1)),o[23]||(o[23]=e("hr",null,null,-1)),o[24]||(o[24]=e("p",null,[e("img",{src:"http://cdn.arstechnica.net/wp-content//uploads/authors/ron-amadeo-sq.jpg",alt:"Ron Amadeo"})],-1)),e("p",null,[n(a,{href:"http://arstechnica.com/author/ronamadeo"},{default:l(()=>[...o[6]||(o[6]=[t("Ron Amadeo",-1)])]),_:1}),o[8]||(o[8]=t(" / Ron是Ars Technica的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。",-1)),n(a,{href:"https://twitter.com/RonAmadeo"},{default:l(()=>[...o[7]||(o[7]=[t("@RonAmadeo",-1)])]),_:1})]),o[25]||(o[25]=e("hr",null,null,-1)),e("p",null,[o[10]||(o[10]=t("via: ",-1)),n(a,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/24/"},{default:l(()=>[...o[9]||(o[9]=[t("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/24/",-1)])]),_:1})]),e("p",null,[o[13]||(o[13]=t("譯者：",-1)),n(a,{href:"https://github.com/alim0x"},{default:l(()=>[...o[11]||(o[11]=[t("alim0x",-1)])]),_:1}),o[14]||(o[14]=t(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:l(()=>[...o[12]||(o[12]=[t("wxy",-1)])]),_:1})]),e("p",null,[o[17]||(o[17]=t("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...o[15]||(o[15]=[t("LCTT",-1)])]),_:1}),o[18]||(o[18]=t(" 原創翻譯，",-1)),n(a,{href:"http://linux.cn/"},{default:l(()=>[...o[16]||(o[16]=[t("Linux中國",-1)])]),_:1}),o[19]||(o[19]=t(" 榮譽推出",-1))])])}const w=i(m,[["render",g]]);export{G as __pageData,w as default};
